(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-080"]={"sura":80,"name_ar":"عبس","name_en":"'Abasa","verses":42,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":42,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=16\" class=\"link\">80:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>சூரா 'அபஸ (முகஞ்சுளித்தார்)</strong><br />\r\n<strong>(வசனங்கள்: 42)</strong><br />\r\n<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)<br />\r\n<br />\r\n<strong>ஒரு பலவீனமான மனிதரைக் கண்டு முகம் சுளித்ததற்காக நபி (ஸல்) அவர்கள் கண்டிக்கப்படுதல்</strong><br />\r\n<br />\r\nதஃப்ஸீர் அறிஞர்களில் பலர் குறிப்பிட்டுள்ளவாறு: ஒருநாள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் குறைஷிக் குலத்தின் முக்கியத் தலைவர்களில் ஒருவரிடம், அவர் இஸ்லாத்தை ஏற்றுக்கொள்வார் என்ற நம்பிக்கையில் உரையாடிக்கொண்டிருந்தார்கள். அவர்கள் அவரிடம் நேரிடையாகப் பேசிக்கொண்டிருந்தபோது, ஆரம்பகாலத்திலேயே இஸ்லாத்தை ஏற்றவர்களில் ஒருவரான இப்னு உம்மி மக்தூம் (ரழி) அவர்கள் அங்கு வந்தார்கள். அவர் (இப்னு உம்மி மக்தூம் (ரழி)) ஏதோ ஒரு விஷயத்தைப் பற்றி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அவசரமாகக் கேட்கத் தொடங்கினார்கள். அந்தத் தலைவர் நேர்வழி பெறுவார் என்று நபி (ஸல்) அவர்கள் நம்பியதால், தமது உரையாடலை முடிக்கும் வரை சற்றுப் பொறுத்திருக்குமாறு இப்னு உம்மி மக்தூம் (ரழி) அவர்களைக் கேட்டுக்கொண்டார்கள். பின்னர் இப்னு உம்மி மக்தூம் (ரழி) அவர்களை நோக்கி முகம் சுளித்துவிட்டு, மற்றவரை நோக்கித் திரும்பினார்கள். அப்போது அல்லாஹ் இதனை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَبَسَ</span> <span class=\"quran-arabic-font text-success\">وَتَوَلَّى</span> - <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">جَآءَهُ</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَى</span> - <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُدْرِيكَ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُ</span> <span class=\"quran-arabic-font text-success\">يَزَّكَّى</span><br />\r\n<br />\r\n(அவர் முகம் சுளித்துத் திரும்பிக்கொண்டார்; அவரிடம் அந்தப் பார்வையற்றவர் வந்தபோது. அவர் தூய்மையடையக்கூடும் என்பதை உமக்கு எது அறிவிக்கும்?) அதாவது, அவர் தனது ஆன்மாவில் தூய்மையையும் பரிசுத்தத்தையும் அடையக்கூடும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَذَّكَّرُ</span> <span class=\"quran-arabic-font text-success\">فَتَنفَعَهُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span><br />\r\n<br />\r\n(அல்லது அவர் நல்லறிவு பெறக்கூடும்; அந்த நல்லறிவு அவருக்குப் பயனளிக்கக்கூடும்) அதாவது, அவர் அறிவுரை பெற்று விலக்கப்பட்டவற்றிலிருந்து விலகியிருக்கக்கூடும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَغْنَى</span> - <span class=\"quran-arabic-font text-success\">فَأَنتَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">تَصَدَّى</span><br />\r\n<br />\r\n(யார் தன்னைத் தேவையற்றவராகக் கருதுகிறாரோ, அவரிடம் நீர் கவனம் செலுத்துகிறீர்;) அதாவது, 'நீர் அந்தச் செல்வந்தரை அவர் நேர்வழி பெறக்கூடும் என்ற நோக்கில் எதிர்கொள்கிறீர்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">يَزَّكَّى</span><br />\r\n<br />\r\n(அவர் தூய்மையடையாவிட்டால் உம்மீது எந்தக் குற்றமுமில்லை.) அதாவது, 'அவர் தூய்மையடையாவிட்டால் அதற்கு நீர் பொறுப்பல்ல.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">جَآءَكَ</span> <span class=\"quran-arabic-font text-success\">يَسْعَى</span> - <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(ஆனால், உம்மிடம் ஆர்வத்துடன் ஓடிவந்தவரோ, அவர் அஞ்சுகிறார்.) அதாவது, 'அவர் உம்மைத் தேடி வரும்போது, நீர் அவரிடம் கூறும் போதனைகள் மூலம் அவர் நேர்வழி பெறுவதையே நாடுகிறார்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنتَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">تَلَهَّى</span><br />\r\n<br />\r\n(அவரை விடுத்து (மற்றவர் பக்கம்) கவனத்தைத் திருப்புகிறீர்.) அதாவது, 'நீர் வேலையாக இருக்கிறீர்.' இங்கே அல்லாஹ் தனது தூதருக்கு (ஸல்), எச்சரிக்கை செய்வதில் யாரையும் தனிமைப்படுத்த வேண்டாம் என்று கட்டளையிடுகிறான். மாறாக, உயர்ந்தவர் மற்றும் பலவீனமானவர், ஏழை மற்றும் பணக்காரர், எஜமானர் மற்றும் அடிமை, ஆண்கள் மற்றும் பெண்கள், சிறியவர் மற்றும் பெரியவர் என அனைவருக்கும் சமமாக எச்சரிக்கை செய்ய வேண்டும். பின்னர் அல்லாஹ் தான் நாடியவரை நேர்வழியில் செலுத்துகிறான். அவனிடம் ஆழமான ஞானமும் உறுதியான ஆதாரமும் உள்ளன. அபூ யஃலா மற்றும் இப்னு ஜரீர் ஆகிய இருவரும் ஆயிஷா (ரழி) அவர்கள் மூலம் பின்வருமாறு அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَبَسَ</span> <span class=\"quran-arabic-font text-success\">وَتَوَلَّى</span><br />\r\n<br />\r\n(அவர் முகம் சுளித்துத் திரும்பிக்கொண்டார்.) எனும் இந்த வசனங்கள் (இச்சம்பவம் குறித்தே) அருளப்பட்டன. அத்-திர்மிதி இந்த ஹதீஸைப் பதிவு செய்துள்ளார். இமாம் மாலிக் (ரஹ்) இதனை 'அல்-முவத்தா'வில் முர்ஸலாகப் (நபித்தோழர் பெயர் விடுபட்ட நிலையில்) பதிவு செய்துள்ளார் என்று நான் கூறுகிறேன்.<br />\r\n<br />\r\n<strong>குர்ஆனின் பண்புகள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةٌ</span><br />\r\n<br />\r\n(அப்படியல்ல! நிச்சயமாக இது ஒரு நல்லறிவுரையாகும்.) அதாவது, இந்த அத்தியாயம் அல்லது மக்களுக்கு அவர்களின் அந்தஸ்தைப் பாராமல் சமமாக அறிவை வழங்குவதில் உள்ள இந்த அறிவுரை. கதாதா மற்றும் அஸ்-ஸுத்தீ ஆகிய இருவரும் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةٌ</span><br />\r\n<br />\r\n\"இதன் பொருள் குர்ஆன் என்பதாகும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">ذَكَرَهُ</span><br />\r\n<br />\r\n(எனவே, யார் விரும்புகிறாரோ அவர் அதனை நினைவில் கொள்ளட்டும்.) அதாவது, யார் விரும்புகிறாரோ அவர் தனது அனைத்துக் காரியங்களிலும் அல்லாஹ்வை நினைவு கூர்கிறார். இந்த இடத்தில் உள்ள பிரதிபெயர்ச்சொல் வஹீயை (இறைச்செய்தி) குறிப்பதாகவும் எடுத்துக்கொள்ளலாம்; ஏனெனில் இந்த உரையாடல் அதையே குறிப்பிடுகிறது. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صُحُفٍ</span> <span class=\"quran-arabic-font text-success\">مُّكَرَّمَةٍ</span> - <span class=\"quran-arabic-font text-success\">مَّرْفُوعَةٍ</span> <span class=\"quran-arabic-font text-success\">مُّطَهَّرَةٍ</span><br />\r\n<br />\r\n(கண்ணியப்படுத்தப்பட்ட, உயர்ந்த, பரிசுத்தமான ஏடுகளில் உள்ளது.) அதாவது, இந்த அத்தியாயம் அல்லது இந்த அறிவுரை. இந்த இரண்டு அர்த்தங்களுமே ஒன்றுக்கொன்று தொடர்புடையவை. உண்மையில், குர்ஆன் முழுவதும் கண்ணியமான ஏடுகளில் உள்ளது, அதாவது அது மதிக்கத்தக்கதும் போற்றத்தக்கதும் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّرْفُوعَةٍ</span><br />\r\n<br />\r\n(உயர்ந்தப்பட்டது) அதாவது, அதன் அந்தஸ்தில் உயர்ந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُّطَهَّرَةٍ</span><br />\r\n<br />\r\n(பரிசுத்தமானது) அதாவது, அசுத்தம், மேலதிகச் சேர்க்கைகள் மற்றும் குறைபாடுகளிலிருந்து தூய்மையானது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِأَيْدِي</span> <span class=\"quran-arabic-font text-success\">سَفَرَةٍ</span><br />\r\n<br />\r\n(தூதுவர்களின் (ஸஃபரா) கரங்களால்;) இப்னு அப்பாஸ் (ரழி), முஜாஹித், அத்-தஹ்ஹாக் மற்றும் இப்னு ஜைத் ஆகியோர், \"இவர்கள் வானவர்கள்\" என்று கூறினார்கள். அல்-புகாரி கூறுகிறார்கள்: \"ஸஃபரா (தூதுவர்கள்) என்பது வானவர்களைக் குறிக்கும். அவர்கள் மக்களிடையே விஷயங்களைச் சீர்திருத்துகிறார்கள். ஒரு தூதுவர் மக்களிடையே விஷயங்களைச் சீர்செய்வது போல, வானவர்கள் அல்லாஹ்வின் வஹீயை (இறைச்செய்தி) சுமந்து இறங்கும்போதும் செயல்படுகிறார்கள்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كِرَامٍ</span> <span class=\"quran-arabic-font text-success\">بَرَرَةٍ</span><br />\r\n<br />\r\n(கண்ணியமான, கீழ்ப்படிதலுள்ளவர்கள்.) அதாவது, அவர்கள் தங்கள் படைப்பில் கண்ணியமானவர்களும் அழகானவர்களும் ஆவர். அவர்களின் குணமும் செயல்களும் நீதியானவை, தூய்மையானவை மற்றும் முழுமையானவை. எனவே, குர்ஆனைச் சுமப்பவர் (ஓதுபவர்), இவர்களைப் போன்று சொல்லிலும் செயலிலும் நேர்மையானவராகவும், நல்வழியைக் கடைப்பிடிப்பவராகவும் இருக்க வேண்டும் என்பது இங்கே குறிப்பிடத்தக்கது. இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்கள் மூலம் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">يَقْرَأُ</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مَاهِرٌ</span> <span class=\"quran-arabic-font text-success\">بِهِ،</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">السَّفَرَةِ</span> <span class=\"quran-arabic-font text-success\">الْكِرَامِ</span> <span class=\"quran-arabic-font text-success\">الْبَرَرَةِ،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">يَقْرَؤُهُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">شَاقٌّ،</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرَان</span>»<br />\r\n<br />\r\n(குர்ஆனைத் திறமையாக ஓதுபவர், கண்ணியமான, நீதியான தூதுவர்களான வானவர்களுடன் இருப்பார். சிரமத்துடன் திக்கித் திக்கி ஓதுபவருக்கு இரண்டு நன்மைகள் உண்டு.) இந்த ஹதீஸை ஹதீஸ் கலை அறிஞர்கள் குழுவினர் பதிவு செய்துள்ளனர்.<br />\r\n<br />","text":"சூரா 'அபஸ (முகஞ்சுளித்தார்)\n\r\n(வசனங்கள்: 42)\n\r\nமக்காவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)\n\r\n\n\r\nஒரு பலவீனமான மனிதரைக் கண்டு முகம் சுளித்ததற்காக நபி (ஸல்) அவர்கள் கண்டிக்கப்படுதல்\n\r\n\n\r\nதஃப்ஸீர் அறிஞர்களில் பலர் குறிப்பிட்டுள்ளவாறு: ஒருநாள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் குறைஷிக் குலத்தின் முக்கியத் தலைவர்களில் ஒருவரிடம், அவர் இஸ்லாத்தை ஏற்றுக்கொள்வார் என்ற நம்பிக்கையில் உரையாடிக்கொண்டிருந்தார்கள். அவர்கள் அவரிடம் நேரிடையாகப் பேசிக்கொண்டிருந்தபோது, ஆரம்பகாலத்திலேயே இஸ்லாத்தை ஏற்றவர்களில் ஒருவரான இப்னு உம்மி மக்தூம் (ரழி) அவர்கள் அங்கு வந்தார்கள். அவர் (இப்னு உம்மி மக்தூம் (ரழி)) ஏதோ ஒரு விஷயத்தைப் பற்றி அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அவசரமாகக் கேட்கத் தொடங்கினார்கள். அந்தத் தலைவர் நேர்வழி பெறுவார் என்று நபி (ஸல்) அவர்கள் நம்பியதால், தமது உரையாடலை முடிக்கும் வரை சற்றுப் பொறுத்திருக்குமாறு இப்னு உம்மி மக்தூம் (ரழி) அவர்களைக் கேட்டுக்கொண்டார்கள். பின்னர் இப்னு உம்மி மக்தூம் (ரழி) அவர்களை நோக்கி முகம் சுளித்துவிட்டு, மற்றவரை நோக்கித் திரும்பினார்கள். அப்போது அல்லாஹ் இதனை அருளினான்:\n\r\n\n\r\nعَبَسَ وَتَوَلَّى - أَن جَآءَهُ الْأَعْمَى - وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى\n\r\n\n\r\n(அவர் முகம் சுளித்துத் திரும்பிக்கொண்டார்; அவரிடம் அந்தப் பார்வையற்றவர் வந்தபோது. அவர் தூய்மையடையக்கூடும் என்பதை உமக்கு எது அறிவிக்கும்?) அதாவது, அவர் தனது ஆன்மாவில் தூய்மையையும் பரிசுத்தத்தையும் அடையக்கூடும்.\n\r\n\n\r\nأَوْ يَذَّكَّرُ فَتَنفَعَهُ الذِّكْرَى\n\r\n\n\r\n(அல்லது அவர் நல்லறிவு பெறக்கூடும்; அந்த நல்லறிவு அவருக்குப் பயனளிக்கக்கூடும்) அதாவது, அவர் அறிவுரை பெற்று விலக்கப்பட்டவற்றிலிருந்து விலகியிருக்கக்கூடும்.\n\r\n\n\r\nأَمَّا مَنِ اسْتَغْنَى - فَأَنتَ لَهُ تَصَدَّى\n\r\n\n\r\n(யார் தன்னைத் தேவையற்றவராகக் கருதுகிறாரோ, அவரிடம் நீர் கவனம் செலுத்துகிறீர்;) அதாவது, 'நீர் அந்தச் செல்வந்தரை அவர் நேர்வழி பெறக்கூடும் என்ற நோக்கில் எதிர்கொள்கிறீர்.'\n\r\n\n\r\nوَمَا عَلَيْكَ أَلاَّ يَزَّكَّى\n\r\n\n\r\n(அவர் தூய்மையடையாவிட்டால் உம்மீது எந்தக் குற்றமுமில்லை.) அதாவது, 'அவர் தூய்மையடையாவிட்டால் அதற்கு நீர் பொறுப்பல்ல.'\n\r\n\n\r\nوَأَمَّا مَن جَآءَكَ يَسْعَى - وَهُوَ يَخْشَى\n\r\n\n\r\n(ஆனால், உம்மிடம் ஆர்வத்துடன் ஓடிவந்தவரோ, அவர் அஞ்சுகிறார்.) அதாவது, 'அவர் உம்மைத் தேடி வரும்போது, நீர் அவரிடம் கூறும் போதனைகள் மூலம் அவர் நேர்வழி பெறுவதையே நாடுகிறார்.'\n\r\n\n\r\nفَأَنتَ عَنْهُ تَلَهَّى\n\r\n\n\r\n(அவரை விடுத்து (மற்றவர் பக்கம்) கவனத்தைத் திருப்புகிறீர்.) அதாவது, 'நீர் வேலையாக இருக்கிறீர்.' இங்கே அல்லாஹ் தனது தூதருக்கு (ஸல்), எச்சரிக்கை செய்வதில் யாரையும் தனிமைப்படுத்த வேண்டாம் என்று கட்டளையிடுகிறான். மாறாக, உயர்ந்தவர் மற்றும் பலவீனமானவர், ஏழை மற்றும் பணக்காரர், எஜமானர் மற்றும் அடிமை, ஆண்கள் மற்றும் பெண்கள், சிறியவர் மற்றும் பெரியவர் என அனைவருக்கும் சமமாக எச்சரிக்கை செய்ய வேண்டும். பின்னர் அல்லாஹ் தான் நாடியவரை நேர்வழியில் செலுத்துகிறான். அவனிடம் ஆழமான ஞானமும் உறுதியான ஆதாரமும் உள்ளன. அபூ யஃலா மற்றும் இப்னு ஜரீர் ஆகிய இருவரும் ஆயிஷா (ரழி) அவர்கள் மூலம் பின்வருமாறு அறிவிக்கிறார்கள்:\n\r\n\n\r\nعَبَسَ وَتَوَلَّى\n\r\n\n\r\n(அவர் முகம் சுளித்துத் திரும்பிக்கொண்டார்.) எனும் இந்த வசனங்கள் (இச்சம்பவம் குறித்தே) அருளப்பட்டன. அத்-திர்மிதி இந்த ஹதீஸைப் பதிவு செய்துள்ளார். இமாம் மாலிக் (ரஹ்) இதனை 'அல்-முவத்தா'வில் முர்ஸலாகப் (நபித்தோழர் பெயர் விடுபட்ட நிலையில்) பதிவு செய்துள்ளார் என்று நான் கூறுகிறேன்.\n\r\n\n\r\nகுர்ஆனின் பண்புகள்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nكَلاَّ إِنَّهَا تَذْكِرَةٌ\n\r\n\n\r\n(அப்படியல்ல! நிச்சயமாக இது ஒரு நல்லறிவுரையாகும்.) அதாவது, இந்த அத்தியாயம் அல்லது மக்களுக்கு அவர்களின் அந்தஸ்தைப் பாராமல் சமமாக அறிவை வழங்குவதில் உள்ள இந்த அறிவுரை. கதாதா மற்றும் அஸ்-ஸுத்தீ ஆகிய இருவரும் கூறினார்கள்:\n\r\n\n\r\nكَلاَّ إِنَّهَا تَذْكِرَةٌ\n\r\n\n\r\n\"இதன் பொருள் குர்ஆன் என்பதாகும்.\"\n\r\n\n\r\nفَمَن شَآءَ ذَكَرَهُ\n\r\n\n\r\n(எனவே, யார் விரும்புகிறாரோ அவர் அதனை நினைவில் கொள்ளட்டும்.) அதாவது, யார் விரும்புகிறாரோ அவர் தனது அனைத்துக் காரியங்களிலும் அல்லாஹ்வை நினைவு கூர்கிறார். இந்த இடத்தில் உள்ள பிரதிபெயர்ச்சொல் வஹீயை (இறைச்செய்தி) குறிப்பதாகவும் எடுத்துக்கொள்ளலாம்; ஏனெனில் இந்த உரையாடல் அதையே குறிப்பிடுகிறது. அல்லாஹ் கூறினான்:\n\r\n\n\r\nفِي صُحُفٍ مُّكَرَّمَةٍ - مَّرْفُوعَةٍ مُّطَهَّرَةٍ\n\r\n\n\r\n(கண்ணியப்படுத்தப்பட்ட, உயர்ந்த, பரிசுத்தமான ஏடுகளில் உள்ளது.) அதாவது, இந்த அத்தியாயம் அல்லது இந்த அறிவுரை. இந்த இரண்டு அர்த்தங்களுமே ஒன்றுக்கொன்று தொடர்புடையவை. உண்மையில், குர்ஆன் முழுவதும் கண்ணியமான ஏடுகளில் உள்ளது, அதாவது அது மதிக்கத்தக்கதும் போற்றத்தக்கதும் ஆகும்.\n\r\n\n\r\nمَّرْفُوعَةٍ\n\r\n\n\r\n(உயர்ந்தப்பட்டது) அதாவது, அதன் அந்தஸ்தில் உயர்ந்தது.\n\r\n\n\r\nمُّطَهَّرَةٍ\n\r\n\n\r\n(பரிசுத்தமானது) அதாவது, அசுத்தம், மேலதிகச் சேர்க்கைகள் மற்றும் குறைபாடுகளிலிருந்து தூய்மையானது. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை,\n\r\n\n\r\nبِأَيْدِي سَفَرَةٍ\n\r\n\n\r\n(தூதுவர்களின் (ஸஃபரா) கரங்களால்;) இப்னு அப்பாஸ் (ரழி), முஜாஹித், அத்-தஹ்ஹாக் மற்றும் இப்னு ஜைத் ஆகியோர், \"இவர்கள் வானவர்கள்\" என்று கூறினார்கள். அல்-புகாரி கூறுகிறார்கள்: \"ஸஃபரா (தூதுவர்கள்) என்பது வானவர்களைக் குறிக்கும். அவர்கள் மக்களிடையே விஷயங்களைச் சீர்திருத்துகிறார்கள். ஒரு தூதுவர் மக்களிடையே விஷயங்களைச் சீர்செய்வது போல, வானவர்கள் அல்லாஹ்வின் வஹீயை (இறைச்செய்தி) சுமந்து இறங்கும்போதும் செயல்படுகிறார்கள்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nكِرَامٍ بَرَرَةٍ\n\r\n\n\r\n(கண்ணியமான, கீழ்ப்படிதலுள்ளவர்கள்.) அதாவது, அவர்கள் தங்கள் படைப்பில் கண்ணியமானவர்களும் அழகானவர்களும் ஆவர். அவர்களின் குணமும் செயல்களும் நீதியானவை, தூய்மையானவை மற்றும் முழுமையானவை. எனவே, குர்ஆனைச் சுமப்பவர் (ஓதுபவர்), இவர்களைப் போன்று சொல்லிலும் செயலிலும் நேர்மையானவராகவும், நல்வழியைக் கடைப்பிடிப்பவராகவும் இருக்க வேண்டும் என்பது இங்கே குறிப்பிடத்தக்கது. இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்கள் மூலம் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ مَاهِرٌ بِهِ، مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَؤُهُ وَهُوَ عَلَيْهِ شَاقٌّ، لَهُ أَجْرَان»\n\r\n\n\r\n(குர்ஆனைத் திறமையாக ஓதுபவர், கண்ணியமான, நீதியான தூதுவர்களான வானவர்களுடன் இருப்பார். சிரமத்துடன் திக்கித் திக்கி ஓதுபவருக்கு இரண்டு நன்மைகள் உண்டு.) இந்த ஹதீஸை ஹதீஸ் கலை அறிஞர்கள் குழுவினர் பதிவு செய்துள்ளனர்."},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=32\" class=\"link\">80:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:32 ஐ பார்க்கவும்"},"32":{"html":"<strong>மரணத்திற்குப் பிறகான வாழ்வை மறுப்பவர்களுக்கு மறுப்பு</strong><br />\r\n<br />\r\nஉயிர்த்தெழுதலையும் இறுதி ஒன்றுதிரட்டலையும் மறுப்பவர்களை அல்லாஹ் கண்டிக்கிறான். <span class=\"quran-arabic-font text-success\">﴾قُتِلَ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَكْفَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மனிதன் சபிக்கப்படட்டும்!) அத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: <span class=\"quran-arabic-font text-success\">﴾قُتِلَ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ﴿</span> (மனிதன் சபிக்கப்படட்டும்!) \"மனிதன் சாபத்திற்கு ஆளாகட்டும்\" என்று அவர்கள் கூறினார்கள். அபூ மாலிக் அவர்களும் இதைப் போன்றே ஒரு கருத்தைக் கூறினார்கள். \"எந்தவொரு ஆதாரமும் இன்றி, வெறும் அறியாமையாலும், இது நடக்க வாய்ப்பில்லை என்ற தனது எண்ணத்தாலும் அதிகமாக மறுக்கின்ற நிராகரிப்பாளரையே இது குறிக்கிறது\" என்று அவர்கள் கூறினார்கள். இப்னு ஜுரைஜ் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾مَآ</span> <span class=\"quran-arabic-font text-success\">أَكْفَرَهُ﴿</span> (அவன் எவ்வளவு நன்றி கெட்டவனாக இருக்கிறான்!) \"அதாவது, நிராகரிப்பில் இவனை விட மோசமானவர் எவருமில்லை.\" கதாதா அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾مَآ</span> <span class=\"quran-arabic-font text-success\">أَكْفَرَهُ﴿</span> (அவன் எவ்வளவு நன்றி கெட்டவனாக இருக்கிறான்!) \"அதாவது, இவனை விடச் சபிக்கப்பட்டவர் எவருமில்லை.\" பின்னர், அற்பமான ஒரு பொருளிலிருந்து மனிதனை எவ்வாறு படைத்தான் என்பதையும், ஆரம்பத்தில் அவனைப் படைத்ததைப் போலவே மீண்டும் அவனுக்கு உயிர் கொடுக்கத் தான் ஆற்றலுடையவன் என்பதையும் அல்லாஹ் விளக்குகிறான். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾مِنْ</span> <span class=\"quran-arabic-font text-success\">أَىِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُ</span> - <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُّطْفَةٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُ</span> <span class=\"quran-arabic-font text-success\">فَقَدَّرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எந்தப் பொருளிலிருந்து அவனைப் படைத்தான்? ஒரு துளி இந்திரியத்திலிருந்து அவனைப் படைத்து, பிறகு அவனைச் சரியான விகிதத்தில் அமைத்தான்.) அதாவது, அவனது ஆயுட்காலம், வாழ்வாதாரம், செயல்கள் மற்றும் அவன் நற்பாக்கியசாலியா அல்லது துர்ப்பாக்கியசாலியா என்பதை அல்லாஹ் நிர்ணயித்தான். <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلَ</span> <span class=\"quran-arabic-font text-success\">يَسَّرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு, அவனுக்கு வழியை எளிதாக்கினான்.) அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"பிறகு அவன் தனது தாயின் வயிற்றிலிருந்து வெளியே வருவதை அவனுக்கு எளிதாக்கினான்.\" இக்ரிமா, அத்-தஹ்ஹாக், அபூ ஸாலிஹ், கதாதா, அஸ்-ஸுத்தி ஆகியோரும் இதையே கூறினார்கள்; இதுவே இப்னு ஜரீர் அவர்களால் விரும்பப்பட்ட விளக்கமாகும். முஜாஹித் அவர்கள் கூறினார்கள்: \"இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">هَدَيْنَـهُ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلَ</span> <span class=\"quran-arabic-font text-success\">إِمَّا</span> <span class=\"quran-arabic-font text-success\">شَاكِراً</span> <span class=\"quran-arabic-font text-success\">وَإِمَّا</span> <span class=\"quran-arabic-font text-success\">كَفُوراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவனுக்கு வழியைக் காட்டினோம்; அவன் நன்றியுள்ளவனாக இருக்கலாம் அல்லது நன்றி கெட்டவனாக இருக்கலாம்.) (<a href=\"qurandisp.php?sura=76&ayah=3\" class=\"link\">76:3</a>) அதாவது, நாம் அவனுக்கு நேர்வழியைத் தெளிவுபடுத்தி, அதன்படி செயல்படுவதை அவனுக்கு எளிதாக்கினோம்.\" அல்-ஹஸன் மற்றும் இப்னு ஸைத் ஆகியோரும் இதையே கூறினார்கள். இதுவே மிகவும் சரியான கருத்தாகும், அல்லாஹ்வே நன்கறிந்தவன். அல்லாஹ்வின் இந்தக் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَمَاتَهُ</span> <span class=\"quran-arabic-font text-success\">فَأَقْبَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு அவன் அவனை மரணிக்கச் செய்து, அவனது மண்ணறையில் (கப்ரில்) சேர்த்தான்.) மனிதனைப் படைத்த பிறகு, அல்லாஹ் அவனை மரணிக்கச் செய்து, அவனை ஒரு மண்ணறையின் வாசியாக ஆக்குகிறான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">أَنشَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு அவன் நாடும்போது, அவனை மீண்டும் உயிர்ப்பிப்பான்.) அதாவது, அவனது மரணத்திற்குப் பிறகு அவனை மீண்டும் உயிர்த்தெழச் செய்வான். இது 'அல்-பஃத்' (உயிர்த்தெழுதல்) மற்றும் 'அன்-நுஷூர்' (மீண்டும் எழுப்புதல்) என்று அழைக்கப்படுகிறது. <span class=\"quran-arabic-font text-success\">﴾وَمِنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِهِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">تُرَابٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِذَآ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">تَنتَشِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவனுடைய அத்தாட்சிகளில் ஒன்று, அவன் உங்களை மண்ணிலிருந்து படைத்தான்; பிறகு இதோ, நீங்கள் (பூமியில்) பரவி வாழும் மனிதர்களாக இருக்கிறீர்கள்.) (<a href=\"qurandisp.php?sura=30&ayah=20\" class=\"link\">30:20</a>) <span class=\"quran-arabic-font text-success\">﴾وَانظُرْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">العِظَامِ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">نُنشِزُهَا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">نَكْسُوهَا</span> <span class=\"quran-arabic-font text-success\">لَحْمًا﴿</span><br />\r\n<br />\r\n(மேலும் அந்த எலும்புகளைப் பாரும்; அவற்றை நாம் எவ்வாறு ஒன்று சேர்க்கிறோம், பின்னர் அவற்றிற்குச் சதையை அணிவிக்கிறோம்.) (<a href=\"qurandisp.php?sura=2&ayah=259\" class=\"link\">2:259</a>) புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் அல்-அஃமஷ் வழியாக அபூ ஸாலிஹ் மூலம் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">يَبْلَى</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">عَجْبَ</span> <span class=\"quran-arabic-font text-success\">الذَّنَبِ،</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">خُلِقَ،</span> <span class=\"quran-arabic-font text-success\">وَفِيهِ</span> <span class=\"quran-arabic-font text-success\">يُرَكَّب</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆதமின் மகன்களின் (மனிதர்களின்) உடல் அனைத்தும் மக்கிவிடும்; வால் எலும்பைத் தவிர. அதிலிருந்தே மனிதன் படைக்கப்பட்டான், அதைக் கொண்டே அவன் மீண்டும் உருவாக்கப்படுவான்.) அல்லாஹ்வின் இந்தக் கூற்றைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾كَلاَّ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">يَقْضِ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَمَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அப்படியல்ல, அல்லாஹ் அவனுக்குக் கட்டளையிட்டதை அவன் இன்னும் நிறைவேற்றவில்லை.) இப்னு ஜரீர் அவர்கள் கூறினார்கள்: \"அல்லாஹ் கூறுகிறான்: 'அப்படியல்ல, இந்த நிராகரிக்கும் மனிதன் கூறுவது போல விஷயம் இல்லை. தனது உயிரைப் பற்றியும் செல்வத்தைப் பற்றியும் அல்லாஹ்வுக்குச் செய்ய வேண்டிய கடமைகளைத் தான் நிறைவேற்றிவிட்டதாக அவன் வாதிடுகிறான். <span class=\"quran-arabic-font text-success\">﴾لَمَّا</span> <span class=\"quran-arabic-font text-success\">يَقْضِ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَمَرَهُ﴿</span> ஆனால் அவன் அல்லாஹ் கட்டளையிட்ட கடமைகளை இன்னும் முழுமையாக நிறைவேற்றவில்லை.\" இதன் உண்மையான பொருளாக எனக்குத் தோன்றுவது - அல்லாஹ்வே நன்கறிந்தவன் - <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">أَنشَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (பிறகு அவன் நாடும்போது, அவனை மீண்டும் உயிர்ப்பிப்பான்.) என்ற வசனம், அவன் மனிதர்களை உயிர்த்தெழச் செய்வான் என்பதைக் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾كَلاَّ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">يَقْضِ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَمَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அப்படியல்ல, அல்லாஹ் அவனுக்குக் கட்டளையிட்டதை அவன் இன்னும் நிறைவேற்றவில்லை.) என்பதன் பொருள், உலகில் பிறப்பதாக அல்லாஹ் எழுதியுள்ள மனிதகுலம் முழுவதும் தோன்றி, அவர்களது ஆயுட்காலம் முடிந்து, அல்லாஹ் நிர்ணயித்த காலக்கெடு முழுமையடையும் வரை அவன் அவர்களை உயிர்ப்பிக்கவில்லை. நிச்சயமாக, அல்லாஹ் மனிதர்களின் பிறப்பையும் அதன் கால அளவையும் நிர்ணயித்துள்ளான். அந்த அவகாசம் முடிந்ததும், அல்லாஹ் படைப்புகளை உயிர்ப்பித்து, ஆரம்பத்தில் படைத்ததைப் போலவே மீண்டும் அவர்களைப் படைப்பான்.<br />\r\n<br />\r\n<strong>விதைகளின் வளர்ச்சியும் பிற அருட்கொடைகளும் மரணத்திற்குப் பின்னுள்ள வாழ்விற்குச் சான்றாகும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلْيَنظُرِ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">طَعَامِهِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆகவே, மனிதன் தனது உணவை உற்றுப் பார்க்கட்டும்.) இது அல்லாஹ்வின் அருட்கொடைகளைச் சிந்திப்பதற்கான ஒரு அழைப்பாகும். மேலும், உயிரற்ற பூமியிலிருந்து தாவரங்கள் உயிர் பெறுவது என்பது, சிதைந்த எலும்புகளாகவும் தூசியாகவும் மாறிய உடல்களை மீண்டும் உயிர்ப்பிக்க முடியும் என்பதற்கு ஒரு சான்றாகவும் அமைந்துள்ளது. <span class=\"quran-arabic-font text-success\">﴾أَنَّا</span> <span class=\"quran-arabic-font text-success\">صَبَبْنَا</span> <span class=\"quran-arabic-font text-success\">الْمَآءَ</span> <span class=\"quran-arabic-font text-success\">صَبّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாமே மழையைத் தாராளமாகப் பொழியச் செய்கிறோம்.) அதாவது, வானத்திலிருந்து பூமிக்குத் தண்ணீரை இறக்குகிறோம். <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">شَقَقْنَا</span> <span class=\"quran-arabic-font text-success\">الأَرْضَ</span> <span class=\"quran-arabic-font text-success\">شَقّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு நாமே பூமியைப் பிளக்கச் செய்கிறோம்.) அதாவது, தண்ணீரைப் பூமிக்குள் இறங்கச் செய்து, அது மண்ணுக்குள் இருக்கும் விதைகளுடன் கலக்கச் செய்கிறோம். இதிலிருந்து விதைகள் முளைத்து, வளர்ந்து, பூமியின் மேற்பரப்பில் தாவரங்களாகத் தோன்றுகின்றன. <span class=\"quran-arabic-font text-success\">﴾فَأَنبَتْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">حَبّاً</span> - <span class=\"quran-arabic-font text-success\">وَعِنَباً</span> <span class=\"quran-arabic-font text-success\">وَقَضْباً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அதில் தானியங்களையும், திராட்சைகளையும், பசுந்தீவனங்களையும் முளைக்கச் செய்கிறோம்.) 'அல்-ஹப்' என்பது அனைத்து வகையான தானியங்களைக் குறிக்கும். திராட்சை என்பது நன்கு அறியப்பட்டது. 'அல்-கத்ப்' என்பது கால்நடைகள் மேயும் பசுமையான தீவனச் செடிகளாகும். இது 'அல்-கத்' என்றும் அழைக்கப்படும் என்று இப்னு அப்பாஸ் (ரழி), கதாதா, அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறியுள்ளனர். அல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"அல்-கத்ப் என்பது கால்நடைத் தீவனமாகும்.\" <span class=\"quran-arabic-font text-success\">﴾وَزَيْتُوناً﴿</span><br />\r\n<br />\r\n(மேலும் ஆலிவ்களையும்.) இது நன்கு அறியப்பட்டது. இதன் கனியும் அதன் எண்ணெயும் உணவாகப் பயன்படுகின்றன. <span class=\"quran-arabic-font text-success\">﴾وَنَخْلاً﴿</span><br />\r\n<br />\r\n(மேலும் பேரீச்சை மரங்களையும்.) இதன் பழங்கள் காயாகவும், பழுத்த பழமாகவும், உலர்ந்த பேரீச்சையாகவும் உண்ணப்படுகின்றன. மேலும் இதிலிருந்து பழச்சாறுகளும் வினிகரும் தயாரிக்கப்படுகின்றன. <span class=\"quran-arabic-font text-success\">﴾وَحَدَآئِقَ</span> <span class=\"quran-arabic-font text-success\">غُلْباً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அடர்த்தியான சோலைகளையும்.) அதாவது தோட்டங்கள். அல்-ஹஸன் மற்றும் கதாதா ஆகிய இருவரும் கூறினார்கள்: \"குல்ப் என்பது அடர்த்தியாகவும் அழகாகவும் இருக்கும் பேரீச்சைத் தோட்டங்கள்.\" இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் ஆகியோர் கூறினார்கள்: \"இதன் பொருள் ஒன்றுதிரண்டு வளர்ந்திருக்கும் அனைத்தும் ஆகும்.\"<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾وَفَـكِهَةً</span> <span class=\"quran-arabic-font text-success\">وَأَبّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் பழங்களையும், புல்வெளிகளையும்.) 'ஃபாகிஹா' என்பது அனைத்து வகையான பழங்களையும் குறிக்கும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-ஃபாகிஹா என்பது மனிதர்கள் உண்ணும் பழங்கள்; அல்-அப் என்பது கால்நடைகள் மேயும் புற்களாகும்.\" அவரிடமிருந்து வரும் மற்றொரு அறிவிப்பில், \"இது கால்நடைகளுக்கான புல்\" என்று அவர் கூறியுள்ளார். அபூ உபைத் அல்-காசிம் பின் ஸல்லாம் அவர்கள் இப்ராஹிம் அத்-தைமி வழியாக அறிவிப்பதாவது: அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்களிடம் <span class=\"quran-arabic-font text-success\">﴾وَفَـكِهَةً</span> <span class=\"quran-arabic-font text-success\">وَأَبّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும் பழங்களையும், புல்வெளிகளையும்) என்ற வசனத்தைப் பற்றிக் கேட்கப்பட்டபோது, அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் வேதத்தைப் பற்றி எனக்குத் தெரியாத ஒன்றை நான் கூறினால், எந்த வானம் எனக்கு நிழல் தரும்? எந்தப் பூமி என்னைச் சுமக்கும்?\" இப்னு ஜரீர் அவர்கள் அனஸ் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளதாவது: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் <span class=\"quran-arabic-font text-success\">﴾عَبَسَ</span> <span class=\"quran-arabic-font text-success\">وَتَوَلَّى</span> <span class=\"quran-arabic-font text-success\">﴿</span> (அவர் கடுகடுத்துத் திரும்பினார்) என்ற அத்தியாயத்தை ஓதி வந்தார்கள். <span class=\"quran-arabic-font text-success\">﴾وَفَـكِهَةً</span> <span class=\"quran-arabic-font text-success\">وَأَبّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span> என்ற வசனத்தை அடைந்தபோது, \"பழங்கள் (ஃபாகிஹா) என்றால் என்னவென்று நமக்குத் தெரியும், ஆனால் 'அப்' என்றால் என்ன?\" என்று கேட்டுவிட்டு, \"உமர்! உனது வாழ்வின் மீது சத்தியமாக, இது தேவையற்ற நுணுக்கங்களைத் தேடும் சுமையாகும் (அதாவது இதன் பொதுவான பொருள் தெளிவானது, இதன் ஆழமான விளக்கத்தைத் தேடுவது அவசியமற்றது)\" என்று தமக்குத் தாமே கூறிக்கொண்டார்கள். இது ஒரு ஆதாரப்பூர்வமான அறிவிப்பாளர் தொடரைக் கொண்டுள்ளது. இந்த வசனத்தில் கூறப்பட்டுள்ளவை அனைத்தும் பூமியிலிருந்து முளைக்கும் தாவரங்கள் என்பது உமர் (ரழி) அவர்களுக்கும் இதை ஓதும் மற்றவர்களுக்கும் தெளிவாகத் தெரியும்; அதன் நுணுக்கமான விளக்கத்தையே அவர் அவ்வாறு குறிப்பிட்டார். இது அல்லாஹ்வின் இந்தக் கூற்றிலிருந்து தெளிவாகிறது: <span class=\"quran-arabic-font text-success\">﴾فَأَنبَتْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">حَبّاً</span> - <span class=\"quran-arabic-font text-success\">وَعِنَباً</span> <span class=\"quran-arabic-font text-success\">وَقَضْباً</span> - <span class=\"quran-arabic-font text-success\">وَزَيْتُوناً</span> <span class=\"quran-arabic-font text-success\">وَنَخْلاً</span> - <span class=\"quran-arabic-font text-success\">وَحَدَآئِقَ</span> <span class=\"quran-arabic-font text-success\">غُلْباً</span> - <span class=\"quran-arabic-font text-success\">وَفَـكِهَةً</span> <span class=\"quran-arabic-font text-success\">وَأَبّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அதில் தானியங்களையும், திராட்சைகளையும், பசுந்தீவனங்களையும், ஆலிவ்களையும், பேரீச்சை மரங்களையும், அடர்த்தியான சோலைகளையும், பழங்களையும், புல்வெளிகளையும் முளைக்கச் செய்தோம்.) பின்னர் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾مَتَـعاً</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلِأَنْعَامِكُمْ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் ஒரு பயனாகவும் வாழ்வாதாரமாகவும்.) அதாவது, மறுமை நாள் வரும் வரை இவ்வுலகில் உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் இது வாழ்வாதாரமாகும்.<br />\r\n<br />","text":"மரணத்திற்குப் பிறகான வாழ்வை மறுப்பவர்களுக்கு மறுப்பு\n\r\n\n\r\nஉயிர்த்தெழுதலையும் இறுதி ஒன்றுதிரட்டலையும் மறுப்பவர்களை அல்லாஹ் கண்டிக்கிறான். ﴾قُتِلَ الإِنسَـنُ مَآ أَكْفَرَهُ ﴿\n\r\n\n\r\n(மனிதன் சபிக்கப்படட்டும்!) அத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: ﴾قُتِلَ الإِنسَـنُ﴿ (மனிதன் சபிக்கப்படட்டும்!) \"மனிதன் சாபத்திற்கு ஆளாகட்டும்\" என்று அவர்கள் கூறினார்கள். அபூ மாலிக் அவர்களும் இதைப் போன்றே ஒரு கருத்தைக் கூறினார்கள். \"எந்தவொரு ஆதாரமும் இன்றி, வெறும் அறியாமையாலும், இது நடக்க வாய்ப்பில்லை என்ற தனது எண்ணத்தாலும் அதிகமாக மறுக்கின்ற நிராகரிப்பாளரையே இது குறிக்கிறது\" என்று அவர்கள் கூறினார்கள். இப்னு ஜுரைஜ் அவர்கள் கூறினார்கள்: ﴾مَآ أَكْفَرَهُ﴿ (அவன் எவ்வளவு நன்றி கெட்டவனாக இருக்கிறான்!) \"அதாவது, நிராகரிப்பில் இவனை விட மோசமானவர் எவருமில்லை.\" கதாதா அவர்கள் கூறினார்கள்: ﴾مَآ أَكْفَرَهُ﴿ (அவன் எவ்வளவு நன்றி கெட்டவனாக இருக்கிறான்!) \"அதாவது, இவனை விடச் சபிக்கப்பட்டவர் எவருமில்லை.\" பின்னர், அற்பமான ஒரு பொருளிலிருந்து மனிதனை எவ்வாறு படைத்தான் என்பதையும், ஆரம்பத்தில் அவனைப் படைத்ததைப் போலவே மீண்டும் அவனுக்கு உயிர் கொடுக்கத் தான் ஆற்றலுடையவன் என்பதையும் அல்லாஹ் விளக்குகிறான். அல்லாஹ் கூறுகிறான்: ﴾مِنْ أَىِّ شَىْءٍ خَلَقَهُ - مِن نُّطْفَةٍ خَلَقَهُ فَقَدَّرَهُ ﴿\n\r\n\n\r\n(எந்தப் பொருளிலிருந்து அவனைப் படைத்தான்? ஒரு துளி இந்திரியத்திலிருந்து அவனைப் படைத்து, பிறகு அவனைச் சரியான விகிதத்தில் அமைத்தான்.) அதாவது, அவனது ஆயுட்காலம், வாழ்வாதாரம், செயல்கள் மற்றும் அவன் நற்பாக்கியசாலியா அல்லது துர்ப்பாக்கியசாலியா என்பதை அல்லாஹ் நிர்ணயித்தான். ﴾ثُمَّ السَّبِيلَ يَسَّرَهُ ﴿\n\r\n\n\r\n(பிறகு, அவனுக்கு வழியை எளிதாக்கினான்.) அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"பிறகு அவன் தனது தாயின் வயிற்றிலிருந்து வெளியே வருவதை அவனுக்கு எளிதாக்கினான்.\" இக்ரிமா, அத்-தஹ்ஹாக், அபூ ஸாலிஹ், கதாதா, அஸ்-ஸுத்தி ஆகியோரும் இதையே கூறினார்கள்; இதுவே இப்னு ஜரீர் அவர்களால் விரும்பப்பட்ட விளக்கமாகும். முஜாஹித் அவர்கள் கூறினார்கள்: \"இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றது: ﴾إِنَّا هَدَيْنَـهُ السَّبِيلَ إِمَّا شَاكِراً وَإِمَّا كَفُوراً ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் அவனுக்கு வழியைக் காட்டினோம்; அவன் நன்றியுள்ளவனாக இருக்கலாம் அல்லது நன்றி கெட்டவனாக இருக்கலாம்.) (76:3) அதாவது, நாம் அவனுக்கு நேர்வழியைத் தெளிவுபடுத்தி, அதன்படி செயல்படுவதை அவனுக்கு எளிதாக்கினோம்.\" அல்-ஹஸன் மற்றும் இப்னு ஸைத் ஆகியோரும் இதையே கூறினார்கள். இதுவே மிகவும் சரியான கருத்தாகும், அல்லாஹ்வே நன்கறிந்தவன். அல்லாஹ்வின் இந்தக் கூற்றைப் பொறுத்தவரை: ﴾ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ ﴿\n\r\n\n\r\n(பிறகு அவன் அவனை மரணிக்கச் செய்து, அவனது மண்ணறையில் (கப்ரில்) சேர்த்தான்.) மனிதனைப் படைத்த பிறகு, அல்லாஹ் அவனை மரணிக்கச் செய்து, அவனை ஒரு மண்ணறையின் வாசியாக ஆக்குகிறான்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்: ﴾ثُمَّ إِذَا شَآءَ أَنشَرَهُ ﴿\n\r\n\n\r\n(பிறகு அவன் நாடும்போது, அவனை மீண்டும் உயிர்ப்பிப்பான்.) அதாவது, அவனது மரணத்திற்குப் பிறகு அவனை மீண்டும் உயிர்த்தெழச் செய்வான். இது 'அல்-பஃத்' (உயிர்த்தெழுதல்) மற்றும் 'அன்-நுஷூர்' (மீண்டும் எழுப்புதல்) என்று அழைக்கப்படுகிறது. ﴾وَمِنْ ءَايَـتِهِ أَنْ خَلَقَكُمْ مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُمْ بَشَرٌ تَنتَشِرُونَ ﴿\n\r\n\n\r\n(மேலும் அவனுடைய அத்தாட்சிகளில் ஒன்று, அவன் உங்களை மண்ணிலிருந்து படைத்தான்; பிறகு இதோ, நீங்கள் (பூமியில்) பரவி வாழும் மனிதர்களாக இருக்கிறீர்கள்.) (30:20) ﴾وَانظُرْ إِلَى العِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا﴿\n\r\n\n\r\n(மேலும் அந்த எலும்புகளைப் பாரும்; அவற்றை நாம் எவ்வாறு ஒன்று சேர்க்கிறோம், பின்னர் அவற்றிற்குச் சதையை அணிவிக்கிறோம்.) (2:259) புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் அல்-அஃமஷ் வழியாக அபூ ஸாலிஹ் மூலம் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«كُلُّ ابْنِ آدَمَ يَبْلَى إِلَّا عَجْبَ الذَّنَبِ، مِنْهُ خُلِقَ، وَفِيهِ يُرَكَّب»﴿\n\r\n\n\r\n(ஆதமின் மகன்களின் (மனிதர்களின்) உடல் அனைத்தும் மக்கிவிடும்; வால் எலும்பைத் தவிர. அதிலிருந்தே மனிதன் படைக்கப்பட்டான், அதைக் கொண்டே அவன் மீண்டும் உருவாக்கப்படுவான்.) அல்லாஹ்வின் இந்தக் கூற்றைப் பொறுத்தவரை: ﴾كَلاَّ لَمَّا يَقْضِ مَآ أَمَرَهُ ﴿\n\r\n\n\r\n(அப்படியல்ல, அல்லாஹ் அவனுக்குக் கட்டளையிட்டதை அவன் இன்னும் நிறைவேற்றவில்லை.) இப்னு ஜரீர் அவர்கள் கூறினார்கள்: \"அல்லாஹ் கூறுகிறான்: 'அப்படியல்ல, இந்த நிராகரிக்கும் மனிதன் கூறுவது போல விஷயம் இல்லை. தனது உயிரைப் பற்றியும் செல்வத்தைப் பற்றியும் அல்லாஹ்வுக்குச் செய்ய வேண்டிய கடமைகளைத் தான் நிறைவேற்றிவிட்டதாக அவன் வாதிடுகிறான். ﴾لَمَّا يَقْضِ مَآ أَمَرَهُ﴿ ஆனால் அவன் அல்லாஹ் கட்டளையிட்ட கடமைகளை இன்னும் முழுமையாக நிறைவேற்றவில்லை.\" இதன் உண்மையான பொருளாக எனக்குத் தோன்றுவது - அல்லாஹ்வே நன்கறிந்தவன் - ﴾ثُمَّ إِذَا شَآءَ أَنشَرَهُ ﴿ (பிறகு அவன் நாடும்போது, அவனை மீண்டும் உயிர்ப்பிப்பான்.) என்ற வசனம், அவன் மனிதர்களை உயிர்த்தெழச் செய்வான் என்பதைக் குறிக்கிறது. ﴾كَلاَّ لَمَّا يَقْضِ مَآ أَمَرَهُ ﴿\n\r\n\n\r\n(அப்படியல்ல, அல்லாஹ் அவனுக்குக் கட்டளையிட்டதை அவன் இன்னும் நிறைவேற்றவில்லை.) என்பதன் பொருள், உலகில் பிறப்பதாக அல்லாஹ் எழுதியுள்ள மனிதகுலம் முழுவதும் தோன்றி, அவர்களது ஆயுட்காலம் முடிந்து, அல்லாஹ் நிர்ணயித்த காலக்கெடு முழுமையடையும் வரை அவன் அவர்களை உயிர்ப்பிக்கவில்லை. நிச்சயமாக, அல்லாஹ் மனிதர்களின் பிறப்பையும் அதன் கால அளவையும் நிர்ணயித்துள்ளான். அந்த அவகாசம் முடிந்ததும், அல்லாஹ் படைப்புகளை உயிர்ப்பித்து, ஆரம்பத்தில் படைத்ததைப் போலவே மீண்டும் அவர்களைப் படைப்பான்.\n\r\n\n\r\nவிதைகளின் வளர்ச்சியும் பிற அருட்கொடைகளும் மரணத்திற்குப் பின்னுள்ள வாழ்விற்குச் சான்றாகும்\n\r\n\n\r\n﴾فَلْيَنظُرِ الإِنسَـنُ إِلَى طَعَامِهِ ﴿\n\r\n\n\r\n(ஆகவே, மனிதன் தனது உணவை உற்றுப் பார்க்கட்டும்.) இது அல்லாஹ்வின் அருட்கொடைகளைச் சிந்திப்பதற்கான ஒரு அழைப்பாகும். மேலும், உயிரற்ற பூமியிலிருந்து தாவரங்கள் உயிர் பெறுவது என்பது, சிதைந்த எலும்புகளாகவும் தூசியாகவும் மாறிய உடல்களை மீண்டும் உயிர்ப்பிக்க முடியும் என்பதற்கு ஒரு சான்றாகவும் அமைந்துள்ளது. ﴾أَنَّا صَبَبْنَا الْمَآءَ صَبّاً ﴿\n\r\n\n\r\n(நிச்சயமாக நாமே மழையைத் தாராளமாகப் பொழியச் செய்கிறோம்.) அதாவது, வானத்திலிருந்து பூமிக்குத் தண்ணீரை இறக்குகிறோம். ﴾ثُمَّ شَقَقْنَا الأَرْضَ شَقّاً ﴿\n\r\n\n\r\n(பிறகு நாமே பூமியைப் பிளக்கச் செய்கிறோம்.) அதாவது, தண்ணீரைப் பூமிக்குள் இறங்கச் செய்து, அது மண்ணுக்குள் இருக்கும் விதைகளுடன் கலக்கச் செய்கிறோம். இதிலிருந்து விதைகள் முளைத்து, வளர்ந்து, பூமியின் மேற்பரப்பில் தாவரங்களாகத் தோன்றுகின்றன. ﴾فَأَنبَتْنَا فِيهَا حَبّاً - وَعِنَباً وَقَضْباً ﴿\n\r\n\n\r\n(மேலும் நாம் அதில் தானியங்களையும், திராட்சைகளையும், பசுந்தீவனங்களையும் முளைக்கச் செய்கிறோம்.) 'அல்-ஹப்' என்பது அனைத்து வகையான தானியங்களைக் குறிக்கும். திராட்சை என்பது நன்கு அறியப்பட்டது. 'அல்-கத்ப்' என்பது கால்நடைகள் மேயும் பசுமையான தீவனச் செடிகளாகும். இது 'அல்-கத்' என்றும் அழைக்கப்படும் என்று இப்னு அப்பாஸ் (ரழி), கதாதா, அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறியுள்ளனர். அல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"அல்-கத்ப் என்பது கால்நடைத் தீவனமாகும்.\" ﴾وَزَيْتُوناً﴿\n\r\n\n\r\n(மேலும் ஆலிவ்களையும்.) இது நன்கு அறியப்பட்டது. இதன் கனியும் அதன் எண்ணெயும் உணவாகப் பயன்படுகின்றன. ﴾وَنَخْلاً﴿\n\r\n\n\r\n(மேலும் பேரீச்சை மரங்களையும்.) இதன் பழங்கள் காயாகவும், பழுத்த பழமாகவும், உலர்ந்த பேரீச்சையாகவும் உண்ணப்படுகின்றன. மேலும் இதிலிருந்து பழச்சாறுகளும் வினிகரும் தயாரிக்கப்படுகின்றன. ﴾وَحَدَآئِقَ غُلْباً ﴿\n\r\n\n\r\n(மேலும் அடர்த்தியான சோலைகளையும்.) அதாவது தோட்டங்கள். அல்-ஹஸன் மற்றும் கதாதா ஆகிய இருவரும் கூறினார்கள்: \"குல்ப் என்பது அடர்த்தியாகவும் அழகாகவும் இருக்கும் பேரீச்சைத் தோட்டங்கள்.\" இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் ஆகியோர் கூறினார்கள்: \"இதன் பொருள் ஒன்றுதிரண்டு வளர்ந்திருக்கும் அனைத்தும் ஆகும்.\"\n\r\n\n\r\nஅல்லாஹ் கூறினான்: ﴾وَفَـكِهَةً وَأَبّاً ﴿\n\r\n\n\r\n(மேலும் பழங்களையும், புல்வெளிகளையும்.) 'ஃபாகிஹா' என்பது அனைத்து வகையான பழங்களையும் குறிக்கும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-ஃபாகிஹா என்பது மனிதர்கள் உண்ணும் பழங்கள்; அல்-அப் என்பது கால்நடைகள் மேயும் புற்களாகும்.\" அவரிடமிருந்து வரும் மற்றொரு அறிவிப்பில், \"இது கால்நடைகளுக்கான புல்\" என்று அவர் கூறியுள்ளார். அபூ உபைத் அல்-காசிம் பின் ஸல்லாம் அவர்கள் இப்ராஹிம் அத்-தைமி வழியாக அறிவிப்பதாவது: அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்களிடம் ﴾وَفَـكِهَةً وَأَبّاً ﴿ (மேலும் பழங்களையும், புல்வெளிகளையும்) என்ற வசனத்தைப் பற்றிக் கேட்கப்பட்டபோது, அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் வேதத்தைப் பற்றி எனக்குத் தெரியாத ஒன்றை நான் கூறினால், எந்த வானம் எனக்கு நிழல் தரும்? எந்தப் பூமி என்னைச் சுமக்கும்?\" இப்னு ஜரீர் அவர்கள் அனஸ் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளதாவது: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் ﴾عَبَسَ وَتَوَلَّى ﴿ (அவர் கடுகடுத்துத் திரும்பினார்) என்ற அத்தியாயத்தை ஓதி வந்தார்கள். ﴾وَفَـكِهَةً وَأَبّاً ﴿ என்ற வசனத்தை அடைந்தபோது, \"பழங்கள் (ஃபாகிஹா) என்றால் என்னவென்று நமக்குத் தெரியும், ஆனால் 'அப்' என்றால் என்ன?\" என்று கேட்டுவிட்டு, \"உமர்! உனது வாழ்வின் மீது சத்தியமாக, இது தேவையற்ற நுணுக்கங்களைத் தேடும் சுமையாகும் (அதாவது இதன் பொதுவான பொருள் தெளிவானது, இதன் ஆழமான விளக்கத்தைத் தேடுவது அவசியமற்றது)\" என்று தமக்குத் தாமே கூறிக்கொண்டார்கள். இது ஒரு ஆதாரப்பூர்வமான அறிவிப்பாளர் தொடரைக் கொண்டுள்ளது. இந்த வசனத்தில் கூறப்பட்டுள்ளவை அனைத்தும் பூமியிலிருந்து முளைக்கும் தாவரங்கள் என்பது உமர் (ரழி) அவர்களுக்கும் இதை ஓதும் மற்றவர்களுக்கும் தெளிவாகத் தெரியும்; அதன் நுணுக்கமான விளக்கத்தையே அவர் அவ்வாறு குறிப்பிட்டார். இது அல்லாஹ்வின் இந்தக் கூற்றிலிருந்து தெளிவாகிறது: ﴾فَأَنبَتْنَا فِيهَا حَبّاً - وَعِنَباً وَقَضْباً - وَزَيْتُوناً وَنَخْلاً - وَحَدَآئِقَ غُلْباً - وَفَـكِهَةً وَأَبّاً ﴿\n\r\n\n\r\n(மேலும் நாம் அதில் தானியங்களையும், திராட்சைகளையும், பசுந்தீவனங்களையும், ஆலிவ்களையும், பேரீச்சை மரங்களையும், அடர்த்தியான சோலைகளையும், பழங்களையும், புல்வெளிகளையும் முளைக்கச் செய்தோம்.) பின்னர் அவன் கூறுகிறான்: ﴾مَتَـعاً لَّكُمْ وَلِأَنْعَامِكُمْ ﴿\n\r\n\n\r\n(உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் ஒரு பயனாகவும் வாழ்வாதாரமாகவும்.) அதாவது, மறுமை நாள் வரும் வரை இவ்வுலகில் உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் இது வாழ்வாதாரமாகும்."},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=80&ayah=42\" class=\"link\">80:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 80:42 ஐ பார்க்கவும்"},"42":{"html":"<strong>நியாயத்தீர்ப்பு நாளும், அந்நாளில் மக்கள் தங்கள் உறவினர்களை விட்டும் வெருண்டோடுவதும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">جَاءَتِ</span> <span class=\"quran-arabic-font text-success\">الصَّاخَّةُ</span><br />\r\n<br />\r\n(செவிப்புலனைச் செவிடாக்கும் பேரொலி வரும்போது)<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அஸ்-ஸாஃக்கா (As-Sakhkhah) என்பது மறுமை நாளின் பெயர்களில் ஒன்றாகும். அல்லாஹ் அந்நாளை மகத்துவப்படுத்தியுள்ளான், மேலும் அது குறித்துத் தனது அடியார்களை எச்சரித்துள்ளான்.\" இப்னு ஜரீர் அவர்கள் கூறினார்கள்: \"ஒருவேளை இது ஸூர் (எக்காளம்) ஊதப்படுவதைக் குறிக்கும் பெயராக இருக்கலாம்.\" அல்-பகவி அவர்கள் கூறினார்கள்: \"அஸ்-ஸாஃக்கா என்பது மறுமை நாளின் பேரிடியோசையைக் குறிக்கும். செவிப்புலனைத் துளைத்து, காதுகளைச் செவிடாக்கும் அளவுக்கு அது இருப்பதால் இப்பெயர் சூட்டப்பட்டது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَفِرُّ</span> <span class=\"quran-arabic-font text-success\">الْمَرْءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَخِيهِ</span> - <span class=\"quran-arabic-font text-success\">وَأُمِّهِ</span> <span class=\"quran-arabic-font text-success\">وَأَبِيهِ</span> - <span class=\"quran-arabic-font text-success\">وَصَاحِبَتِهِ</span> <span class=\"quran-arabic-font text-success\">وَبَنِيهِ</span><br />\r\n<br />\r\n(அந்நாளில் மனிதன் தன் சகோதரனை விட்டும், தன் தாயை விட்டும், தன் தந்தையை விட்டும், தன் மனைவியை விட்டும், தன் பிள்ளைகளை விட்டும் வெருண்டோடுவான்.) அதாவது, மனிதன் அவர்களைப் பார்ப்பான், ஆனால் அந்த நடுக்கமும் பயங்கரமும் அவ்வளவு பெரிதாக இருப்பதால், அவர்களை விட்டும் விலகி ஓடவே முயற்சிப்பான். பரிந்துரை (ஷஃபாஅத்) குறித்த ஒரு ஆதாரப்பூர்வமான ஹதீஸில், உறுதிமிக்க (உலுல் அஸ்ம்) மாபெரும் தூதர்களில் ஒவ்வொருவரிடமும் படைப்பினங்களுக்காக அல்லாஹ்விடம் பரிந்துரை செய்யுமாறு கோரப்படும்போது, அவர்கள் ஒவ்வொருவரும், \"என் ஆத்மாவே! என் ஆத்மாவே! இன்று என்னைத் தவிர வேறு எவரைப் பற்றியும் நான் உன்னிடம் (அல்லாஹ்வே) கேட்க மாட்டேன்\" என்று கூறுவார்கள். ஈஸா இப்னு மர்யம் (அலை) அவர்கள் கூட, \"இன்று என்னைத் தவிர வேறு எவரைப் பற்றியும் நான் அவனிடம் (அல்லாஹ்விடம்) கேட்க மாட்டேன். என்னைப் பெற்றெடுத்த மர்யத்தைப் பற்றி கூட நான் கேட்க மாட்டேன்\" என்று கூறுவார்கள். இதையே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَفِرُّ</span> <span class=\"quran-arabic-font text-success\">الْمَرْءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَخِيهِ</span> - <span class=\"quran-arabic-font text-success\">وَأُمِّهِ</span> <span class=\"quran-arabic-font text-success\">وَأَبِيهِ</span> - <span class=\"quran-arabic-font text-success\">وَصَاحِبَتِهِ</span> <span class=\"quran-arabic-font text-success\">وَبَنِيهِ</span><br />\r\n<br />\r\n(அந்நாளில் மனிதன் தன் சகோதரனை விட்டும், தன் தாயை விட்டும், தன் தந்தையை விட்டும், தன் மனைவியை விட்டும், தன் பிள்ளைகளை விட்டும் வெருண்டோடுவான்.) கதாதா அவர்கள் கூறினார்கள்: \"அந்நாளின் திகிலின் காரணமாக, தனக்கு மிகவும் பிரியமானவர்களையும், நெருங்கிய உறவினர்களையும் விட்டும் மனிதன் விலகி ஓடுவான்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">امْرِئٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">شَأْنٌ</span> <span class=\"quran-arabic-font text-success\">يُغْنِيهِ</span><br />\r\n<br />\r\n(அந்நாளில் அவர்கள் ஒவ்வொருவருக்கும் பிறரைப் பற்றி சிந்திக்க விடாதபடி (அவனவனுக்குரிய) ஒரு நிலை இருக்கும்.) அதாவது, ஒவ்வொருவனும் தன் சொந்த விவகாரத்திலேயே மூழ்கிப்போய், மற்றவர்களைக் கவனிக்கும் நிலையில் இருக்கமாட்டான். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تُحْشَرُونَ</span> <span class=\"quran-arabic-font text-success\">حُفَاةً</span> <span class=\"quran-arabic-font text-success\">عُرَاةً</span> <span class=\"quran-arabic-font text-success\">مُشَاةً</span> <span class=\"quran-arabic-font text-success\">غُرْلًا</span>»<br />\r\n<br />\r\n(நீங்கள் அனைவரும் வெறுங்காலுடன், நிர்வாணமாக, நடந்தவர்களாக, விருத்தசேதனம் செய்யப்படாதவர்களாக ஒன்றுதிரட்டப்படுவீர்கள்.) அப்போது ஒரு மனைவி (ஆயிஷா (ரழி)), \"அல்லாஹ்வின் தூதரே! நாம் ஒருவரையொருவர் அல்லது ஒருவருடைய நிர்வாணத்தை ஒருவர் பார்ப்போமா?\" என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">امْرِئٍ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">شَأْنٌ</span> <span class=\"quran-arabic-font text-success\">يُغْنِيهِ</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَشْغَلَهُ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">النَّظَر</span>»<br />\r\n<br />\r\n(அந்நாளில் அவர்கள் ஒவ்வொருவருக்கும் பிறரைப் பற்றி கவலைப்பட முடியாத அளவுக்குத் தன் சொந்தக் கவலைகளே போதுமானதாக இருக்கும்) - அல்லது அவர்கள் கூறினார்கள்: (நிர்வாணத்தைப் பார்ப்பதை விட்டும் அவனைத் தடுத்துவிடும் அளவுக்கு அவன் தன் காரியத்தில் மும்முரமாக இருப்பான்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்தார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تُحْشَرُونَ</span> <span class=\"quran-arabic-font text-success\">حُفَاةً</span> <span class=\"quran-arabic-font text-success\">عُرَاةً</span> <span class=\"quran-arabic-font text-success\">غُرْلًا</span>»<br />\r\n<br />\r\n(நீங்கள் அனைவரும் வெறுங்காலுடன், நிர்வாணமாக, விருத்தசேதனம் செய்யப்படாதவர்களாக ஒன்றுதிரட்டப்படுவீர்கள்.) அப்போது ஒரு பெண்மணி, \"நாம் ஒருவருடைய நிர்வாணத்தை ஒருவர் பார்ப்போமா?\" என்று கேட்டார். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">فُلَانَةُ،</span> <span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">امْرِئٍ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">شَأْنٌ</span> <span class=\"quran-arabic-font text-success\">يُغْنِيه</span>»<br />\r\n<br />\r\n(ஓ இன்னாரே! அந்நாளில் அவர்கள் ஒவ்வொருவருக்கும் பிறரைப் பற்றி கவலைப்பட முடியாத அளவுக்குத் தன் சொந்தக் கவலைகளே போதுமானதாக இருக்கும்.) அத்-திர்மிதி அவர்கள் கூறினார்கள், \"இந்த ஹதீஸ் ஹஸன் ஸஹீஹ் ஆகும்.\"<br />\r\n<br />\r\n<strong>நியாயத்தீர்ப்பு நாளில் சொர்க்கவாசிகளின் மற்றும் நரகவாசிகளின் முகங்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وُجُوهٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْفِرَةٌ</span> - <span class=\"quran-arabic-font text-success\">ضَاحِكَةٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَبْشِرَةٌ</span><br />\r\n<br />\r\n(அந்நாளில் சில முகங்கள் பிரகாசமாக (முஸ்ஃபிரஹ்) இருக்கும். சிரித்தவையாக, நற்செய்தியால் மகிழ்ச்சியடைந்தவையாக இருக்கும்.) அதாவது, மக்கள் அன்று இரண்டு பிரிவுகளாகப் பிரிக்கப்படுவார்கள். சில முகங்கள் 'முஸ்ஃபிரஹ்' ஆக, அதாவது ஒளி வீசுபவையாக இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ضَاحِكَةٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَبْشِرَةٌ</span><br />\r\n<br />\r\n(சிரித்தவையாக, நற்செய்தியால் மகிழ்ச்சியடைந்தவையாக.) அதாவது, அவர்களின் உள்ளங்களில் இருக்கும் சந்தோஷத்தின் காரணமாக மகிழ்ச்சியுடனும் திருப்தியுடனும் இருப்பார்கள். அந்த நற்செய்தியின் பொலிவு அவர்கள் முகங்களில் வெளிப்படும். இவர்களே சொர்க்கவாசிகள் ஆவர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَوُجُوهٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">غَبَرَةٌ</span> - <span class=\"quran-arabic-font text-success\">تَرْهَقُهَا</span> <span class=\"quran-arabic-font text-success\">قَتَرَةٌ</span><br />\r\n<br />\r\n(மேலும் அந்நாளில் வேறு சில முகங்கள் மீது புழுதி படிந்திருக்கும். அவற்றை இருள் (கதரா) மூடியிருக்கும்.) அதாவது, அந்த முகங்கள் இருளாலும் கருமையாலும் சூழப்பட்டிருக்கும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَرْهَقُهَا</span> <span class=\"quran-arabic-font text-success\">قَتَرَةٌ</span><br />\r\n<br />\r\n(அவற்றை இருள் (கதரா) மூடியிருக்கும்.) \"இதன் பொருள், அந்த முகங்கள் இருளால் கம்மியிருக்கும் என்பதாகும்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْكَفَرَةُ</span> <span class=\"quran-arabic-font text-success\">الْفَجَرَةُ</span><br />\r\n<br />\r\n(இத்தகையோர்தான் நிராகரிப்பாளர்களும், தீயவர்களும் ஆவர்.) அதாவது, அவர்கள் உள்ளத்தால் இறைமறுப்பாளர்களாகவும், செயல்களால் பாவம் செய்பவர்களாகவும் இருந்தனர். இது அல்லாஹ் கூறுவதைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَلِدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فَاجِراً</span> <span class=\"quran-arabic-font text-success\">كَفَّاراً</span><br />\r\n<br />\r\n(மேலும், அவர்கள் தீயவர்களையும் நிராகரிப்பவர்களையும் தவிர வேறெவரையும் பெற்றெடுக்க மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=71&ayah=27\" class=\"link\">71:27</a>) இத்துடன் ஸூரா 'அபஸ'வின் தஃப்ஸீர் நிறைவு பெற்றது. புகழனைத்தும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"நியாயத்தீர்ப்பு நாளும், அந்நாளில் மக்கள் தங்கள் உறவினர்களை விட்டும் வெருண்டோடுவதும்\n\r\n\n\r\nفَإِذَا جَاءَتِ الصَّاخَّةُ\n\r\n\n\r\n(செவிப்புலனைச் செவிடாக்கும் பேரொலி வரும்போது)\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அஸ்-ஸாஃக்கா (As-Sakhkhah) என்பது மறுமை நாளின் பெயர்களில் ஒன்றாகும். அல்லாஹ் அந்நாளை மகத்துவப்படுத்தியுள்ளான், மேலும் அது குறித்துத் தனது அடியார்களை எச்சரித்துள்ளான்.\" இப்னு ஜரீர் அவர்கள் கூறினார்கள்: \"ஒருவேளை இது ஸூர் (எக்காளம்) ஊதப்படுவதைக் குறிக்கும் பெயராக இருக்கலாம்.\" அல்-பகவி அவர்கள் கூறினார்கள்: \"அஸ்-ஸாஃக்கா என்பது மறுமை நாளின் பேரிடியோசையைக் குறிக்கும். செவிப்புலனைத் துளைத்து, காதுகளைச் செவிடாக்கும் அளவுக்கு அது இருப்பதால் இப்பெயர் சூட்டப்பட்டது.\"\n\r\n\n\r\nيَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ - وَأُمِّهِ وَأَبِيهِ - وَصَاحِبَتِهِ وَبَنِيهِ\n\r\n\n\r\n(அந்நாளில் மனிதன் தன் சகோதரனை விட்டும், தன் தாயை விட்டும், தன் தந்தையை விட்டும், தன் மனைவியை விட்டும், தன் பிள்ளைகளை விட்டும் வெருண்டோடுவான்.) அதாவது, மனிதன் அவர்களைப் பார்ப்பான், ஆனால் அந்த நடுக்கமும் பயங்கரமும் அவ்வளவு பெரிதாக இருப்பதால், அவர்களை விட்டும் விலகி ஓடவே முயற்சிப்பான். பரிந்துரை (ஷஃபாஅத்) குறித்த ஒரு ஆதாரப்பூர்வமான ஹதீஸில், உறுதிமிக்க (உலுல் அஸ்ம்) மாபெரும் தூதர்களில் ஒவ்வொருவரிடமும் படைப்பினங்களுக்காக அல்லாஹ்விடம் பரிந்துரை செய்யுமாறு கோரப்படும்போது, அவர்கள் ஒவ்வொருவரும், \"என் ஆத்மாவே! என் ஆத்மாவே! இன்று என்னைத் தவிர வேறு எவரைப் பற்றியும் நான் உன்னிடம் (அல்லாஹ்வே) கேட்க மாட்டேன்\" என்று கூறுவார்கள். ஈஸா இப்னு மர்யம் (அலை) அவர்கள் கூட, \"இன்று என்னைத் தவிர வேறு எவரைப் பற்றியும் நான் அவனிடம் (அல்லாஹ்விடம்) கேட்க மாட்டேன். என்னைப் பெற்றெடுத்த மர்யத்தைப் பற்றி கூட நான் கேட்க மாட்டேன்\" என்று கூறுவார்கள். இதையே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ - وَأُمِّهِ وَأَبِيهِ - وَصَاحِبَتِهِ وَبَنِيهِ\n\r\n\n\r\n(அந்நாளில் மனிதன் தன் சகோதரனை விட்டும், தன் தாயை விட்டும், தன் தந்தையை விட்டும், தன் மனைவியை விட்டும், தன் பிள்ளைகளை விட்டும் வெருண்டோடுவான்.) கதாதா அவர்கள் கூறினார்கள்: \"அந்நாளின் திகிலின் காரணமாக, தனக்கு மிகவும் பிரியமானவர்களையும், நெருங்கிய உறவினர்களையும் விட்டும் மனிதன் விலகி ஓடுவான்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nلِكُلِّ امْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ\n\r\n\n\r\n(அந்நாளில் அவர்கள் ஒவ்வொருவருக்கும் பிறரைப் பற்றி சிந்திக்க விடாதபடி (அவனவனுக்குரிய) ஒரு நிலை இருக்கும்.) அதாவது, ஒவ்வொருவனும் தன் சொந்த விவகாரத்திலேயே மூழ்கிப்போய், மற்றவர்களைக் கவனிக்கும் நிலையில் இருக்கமாட்டான். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«تُحْشَرُونَ حُفَاةً عُرَاةً مُشَاةً غُرْلًا»\n\r\n\n\r\n(நீங்கள் அனைவரும் வெறுங்காலுடன், நிர்வாணமாக, நடந்தவர்களாக, விருத்தசேதனம் செய்யப்படாதவர்களாக ஒன்றுதிரட்டப்படுவீர்கள்.) அப்போது ஒரு மனைவி (ஆயிஷா (ரழி)), \"அல்லாஹ்வின் தூதரே! நாம் ஒருவரையொருவர் அல்லது ஒருவருடைய நிர்வாணத்தை ஒருவர் பார்ப்போமா?\" என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n«لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ أو قال: مَا أَشْغَلَهُ عَنِ النَّظَر»\n\r\n\n\r\n(அந்நாளில் அவர்கள் ஒவ்வொருவருக்கும் பிறரைப் பற்றி கவலைப்பட முடியாத அளவுக்குத் தன் சொந்தக் கவலைகளே போதுமானதாக இருக்கும்) - அல்லது அவர்கள் கூறினார்கள்: (நிர்வாணத்தைப் பார்ப்பதை விட்டும் அவனைத் தடுத்துவிடும் அளவுக்கு அவன் தன் காரியத்தில் மும்முரமாக இருப்பான்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்தார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«تُحْشَرُونَ حُفَاةً عُرَاةً غُرْلًا»\n\r\n\n\r\n(நீங்கள் அனைவரும் வெறுங்காலுடன், நிர்வாணமாக, விருத்தசேதனம் செய்யப்படாதவர்களாக ஒன்றுதிரட்டப்படுவீர்கள்.) அப்போது ஒரு பெண்மணி, \"நாம் ஒருவருடைய நிர்வாணத்தை ஒருவர் பார்ப்போமா?\" என்று கேட்டார். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n«يَا فُلَانَةُ، لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيه»\n\r\n\n\r\n(ஓ இன்னாரே! அந்நாளில் அவர்கள் ஒவ்வொருவருக்கும் பிறரைப் பற்றி கவலைப்பட முடியாத அளவுக்குத் தன் சொந்தக் கவலைகளே போதுமானதாக இருக்கும்.) அத்-திர்மிதி அவர்கள் கூறினார்கள், \"இந்த ஹதீஸ் ஹஸன் ஸஹீஹ் ஆகும்.\"\n\r\n\n\r\nநியாயத்தீர்ப்பு நாளில் சொர்க்கவாசிகளின் மற்றும் நரகவாசிகளின் முகங்கள்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ - ضَاحِكَةٌ مُّسْتَبْشِرَةٌ\n\r\n\n\r\n(அந்நாளில் சில முகங்கள் பிரகாசமாக (முஸ்ஃபிரஹ்) இருக்கும். சிரித்தவையாக, நற்செய்தியால் மகிழ்ச்சியடைந்தவையாக இருக்கும்.) அதாவது, மக்கள் அன்று இரண்டு பிரிவுகளாகப் பிரிக்கப்படுவார்கள். சில முகங்கள் 'முஸ்ஃபிரஹ்' ஆக, அதாவது ஒளி வீசுபவையாக இருக்கும்.\n\r\n\n\r\nضَاحِكَةٌ مُّسْتَبْشِرَةٌ\n\r\n\n\r\n(சிரித்தவையாக, நற்செய்தியால் மகிழ்ச்சியடைந்தவையாக.) அதாவது, அவர்களின் உள்ளங்களில் இருக்கும் சந்தோஷத்தின் காரணமாக மகிழ்ச்சியுடனும் திருப்தியுடனும் இருப்பார்கள். அந்த நற்செய்தியின் பொலிவு அவர்கள் முகங்களில் வெளிப்படும். இவர்களே சொர்க்கவாசிகள் ஆவர்.\n\r\n\n\r\nوَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ - تَرْهَقُهَا قَتَرَةٌ\n\r\n\n\r\n(மேலும் அந்நாளில் வேறு சில முகங்கள் மீது புழுதி படிந்திருக்கும். அவற்றை இருள் (கதரா) மூடியிருக்கும்.) அதாவது, அந்த முகங்கள் இருளாலும் கருமையாலும் சூழப்பட்டிருக்கும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nتَرْهَقُهَا قَتَرَةٌ\n\r\n\n\r\n(அவற்றை இருள் (கதரா) மூடியிருக்கும்.) \"இதன் பொருள், அந்த முகங்கள் இருளால் கம்மியிருக்கும் என்பதாகும்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nأُوْلَـئِكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ\n\r\n\n\r\n(இத்தகையோர்தான் நிராகரிப்பாளர்களும், தீயவர்களும் ஆவர்.) அதாவது, அவர்கள் உள்ளத்தால் இறைமறுப்பாளர்களாகவும், செயல்களால் பாவம் செய்பவர்களாகவும் இருந்தனர். இது அல்லாஹ் கூறுவதைப் போன்றது:\n\r\n\n\r\nوَلاَ يَلِدُواْ إِلاَّ فَاجِراً كَفَّاراً\n\r\n\n\r\n(மேலும், அவர்கள் தீயவர்களையும் நிராகரிப்பவர்களையும் தவிர வேறெவரையும் பெற்றெடுக்க மாட்டார்கள்.) (71:27) இத்துடன் ஸூரா 'அபஸ'வின் தஃப்ஸீர் நிறைவு பெற்றது. புகழனைத்தும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
